                .then(data => {
                    displayGrades(data);
                })
                .catch(error => {
                    console.error('Error fetching grades:', error);
                });
        }

        function displayGrades(data) {
            const tableBody = document.getElementById('tableBody');
            tableBody.innerHTML = '';
            data.forEach(student => {
                const row = document.createElement('tr');
                row.innerHTML = `<td>${student.name}</td><td>${student.score}</td>`;
                tableBody.appendChild(row);
            });
        }

        function sortTable(column) {
            const tableBody = document.getElementById('tableBody');
            const rows = Array.from(tableBody.rows);
            let sortedRows = [...rows];

            if (column === 'name') {
                sortedRows.sort((a, b) => {
                    const nameA = a.cells[0].textContent.toUpperCase();
                    const nameB = b.cells[0].textContent.toUpperCase();
                    return nameA.localeCompare(nameB);
                });
            } else if (column === 'score') {
                sortedRows.sort((a, b) => {
                    return parseFloat(a.cells[1].textContent) - parseFloat(b.cells[1].textContent);
                });
            }

            tableBody.innerHTML = '';
            sortedRows.forEach(row => tableBody.appendChild(row));
        }

