// WeatherApp.js
// This script fetches weather data for multiple cities and displays the results in a table

// Replace with your OpenWeatherMap API key
const API_KEY = 'YOUR_API_KEY';

// Function to fetch weather data for a single city
async function getWeather(city) {
  try {
    const response = await fetch(`https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${API_KEY}&units=metric`);

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const data = await response.json();
    return {
      city: data.name,
      tempCelsius: data.main.temp,
      tempFahrenheit: (data.main.temp * 9/5) + 32
    };
  } catch (error) {
    console.error(`Error fetching weather for ${city}:`, error);
    return { city, error: error.message };
  }
}

// Function to display weather data in a table
function displayWeatherData(weatherData) {
  const tableBody = document.getElementById('weatherTableBody');
  tableBody.innerHTML = ''; // Clear existing data

  weatherData.forEach(entry => {
    const row = document.createElement('tr');

    if (entry.error) {
      // If there's an error, display the error message
      const cell = document.createElement('td');
      cell.colSpan = 3;
      cell.textContent = entry.error;
      cell.style.color = 'red';
      row.appendChild(cell);
    } else {
      // Otherwise, display the city, temperature in Celsius, and Fahrenheit
      const cityCell = document.createElement('td');
      cityCell.textContent = entry.city;

      const celsiusCell = document.createElement('td');
      celsiusCell.textContent = `${entry.tempCelsius.toFixed(1)}°C`;

      const fahrenheitCell = document.createElement('td');
      fahrenheitCell.textContent = `${entry.tempFahrenheit.toFixed(1)}°F`;

      row.appendChild(cityCell);
      row.appendChild(celsiusCell);
      row.appendChild(fahrenheitCell);
    }

    tableBody.appendChild(row);
  });
}

// Function to handle user input and fetch weather data for all cities
async function handleUserInput() {
  const citiesInput = document.getElementById('citiesInput').value;
  const cities = citiesInput.split(',').map(city => city.trim()).filter(city => city !== '');

  if (cities.length === 0) {
    alert('Please enter at least one city name.');
    return;
  }

  // Fetch weather data for all cities concurrently using Promise.all
  const weatherPromises = cities.map(getWeather);
  const weatherData = await Promise.all(weatherPromises);

  displayWeatherData(weatherData);
}

