    pub fn new(address: SocketAddr) -> Self {
        let transport = UdpTransport::new();
        Self { transport, address }
    }

    pub async fn send_request(&self, payload: &[u8]) -> Result<Message, coap::Error> {
        let message = coap::message::Message::new(
            coap::message::Message::Request,
            coap::message::Method::Get,
            coap::message::UriPath::new(vec![]),
            coap::message::UriQuery::new(vec![]),
            payload.to_vec(),
            coap::message::Message::default_options(),
        );
        self.transport.send_to(self.address, message).await
    }

    pub async fn receive_response(&self) -> Result<Message, coap::Error> {
        self.transport.recv_from().await
    }

    pub async fn get_data(&self) -> Result<Vec<u8>, coap::Error> {
        let response = self.send_request(b"").await?;
        let payload = response.payload().to_vec();
        Ok(payload)
    }
}
